const P = [
  ['Mobitrace','14240418673f52ae29a007.74392007'],
  ['Mobitrace - backend/emails','9274956467e3e224807498.79791832'],
  ['My Image - Backend','50011170688b3050b0a7f8.40995136'],
  ['Unicopy','35679002689c4f3ba6dd50.31739712'],
  ['Unicopy (backend)','1600517668d38be7f36ba4.51132642'],
  ['WAPP','4780438967fe077b4e6484.83742970']
];
const out = [];
for (const p of P) {
  out.push({ json: { name: p[0], pid: p[1], kind: 'cts', url: 'https://api.lokalise.com/api2/projects/' + p[1] + '/custom_translation_statuses?limit=100' } });
  out.push({ json: { name: p[0], pid: p[1], kind: 'langs', url: 'https://api.lokalise.com/api2/projects/' + p[1] + '/languages?limit=100' } });
  out.push({ json: { name: p[0], pid: p[1], kind: 'stats', url: 'https://api.lokalise.com/api2/projects/' + p[1] + '?include_statistics=1&include_settings=1' } });
  out.push({ json: { name: p[0], pid: p[1], kind: 'untranslated', url: 'https://api.lokalise.com/api2/projects/' + p[1] + '/keys?filter_untranslated=1&limit=1&page=1' } });
}
return out;

const reqs = $('Config').all();
const res = $input.all();
const out = {};
const errors = [];
for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  if (!out[meta.name]) { out[meta.name] = { pid: meta.pid }; }
  const o = out[meta.name];
  if (r.statusCode !== 200) { errors.push(meta.name + ' ' + meta.kind + ' status ' + r.statusCode + ' ' + JSON.stringify(b).slice(0,150)); continue; }
  if (meta.kind === 'cts') {
    const m = {};
    for (const s of (b.custom_translation_statuses || [])) { m[String(s.status_id)] = s.title; }
    o.statuses = m;
  } else if (meta.kind === 'langs') {
    const l = [];
    for (const x of (b.languages || [])) { l.push(x.lang_iso + ':' + x.lang_id); }
    o.languages = l;
  } else if (meta.kind === 'stats') {
    const p = b.project || {};
    const st = p.statistics || {};
    o.key_count = st.key_count;
    o.progress_total = st.progress_total;
    o.custom_statuses_enabled = (p.settings || {}).custom_translation_statuses;
    const per = [];
    for (const l of (st.languages || [])) { if (l.words_to_do > 0) { per.push(l.language_iso + ':' + l.words_to_do); } }
    o.words_to_do = per;
  } else {
    o.untranslated_keys = (r.headers || {})['x-pagination-total-count'];
  }
}
return [{ json: { projects: out, errors: errors } }];
